// One fixed, non-interactive canvas persists across tabs and scroll positions.
(()=>{const canvas=document.getElementById('site-grid'),ctx=canvas.getContext('2d');const phrases=['Pass the mic.','Change who decides.','Make room for every voice.','No woman in the room?','Pause the decision.'];let timer,visible=true;
function draw(){if(!visible)return;const w=innerWidth,h=innerHeight,d=Math.min(devicePixelRatio||1,2),step=w<600?14:18;canvas.width=w*d;canvas.height=h*d;ctx.scale(d,d);ctx.clearRect(0,0,w,h);ctx.strokeStyle='rgba(0,15,255,.027)';ctx.lineWidth=.5;ctx.beginPath();for(let x=0;x<w;x+=step){ctx.moveTo(x,0);ctx.lineTo(x,h)}for(let y=0;y<h;y+=step){ctx.moveTo(0,y);ctx.lineTo(w,y)}ctx.stroke();ctx.font=`500 ${step*.57}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='rgba(0,15,255,.10)';const epoch=Math.floor(Date.now()/2000);for(let row=0,y=step/2;y<h;y+=step,row++){const phrase=phrases[(row*7+epoch)%phrases.length]+'  ';for(let col=0,x=step/2;x<w;x+=step,col++)ctx.fillText(phrase[(col+row*3)%phrase.length],x,y)}}
function schedule(){clearInterval(timer);visible=!document.hidden;draw();if(visible)timer=setInterval(draw,2000)}addEventListener('resize',draw);document.addEventListener('visibilitychange',schedule);schedule();addEventListener('pagehide',()=>clearInterval(timer));})();
